import React, { useState, useEffect } from 'react';
import styled from 'styled-components';

const ChatbotContainer = styled.div`
  position: fixed;
  bottom: 20px;
  right: 20px;
  width: 400px;
  max-height: 600px;
  border: 1px solid #ddd;
  border-radius: 10px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  background: #fff;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  z-index: 1000;
`;

const ChatbotHeader = styled.div`
  background: #007bff;
  color: white;
  padding: 10px;
  text-align: center;
  font-weight: bold;
  cursor: pointer;
`;

const ChatWindow = styled.div`
  flex: 1;
  padding: 10px;
  overflow-y: auto;
  font-size: 0.9rem;
  color: #333;
`;

const ChatInputContainer = styled.div`
  display: flex;
  padding: 10px;
  border-top: 1px solid #ddd;
`;

const ChatInput = styled.input`
  flex: 1;
  padding: 8px;
  border: 1px solid #ddd;
  border-radius: 5px;
  font-size: 1rem;
`;

const SendButton = styled.button`
  padding: 8px 15px;
  margin-left: 10px;
  border: none;
  background-color: #007bff;
  color: white;
  border-radius: 5px;
  cursor: pointer;

  &:hover {
    background-color: #0056b3;
  }
`;

const Chatbot = () => {
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [isOpen, setIsOpen] = useState(true);
  const [isFirstGreeting, setIsFirstGreeting] = useState(true);

  const knowledgeBase = {
    hello: `Hello! How can I assist you today? Here are a few things I can help with:
- Triathlon basics: Type "beginner".
- Training plans: Type "training".
- Gear recommendations: Type "gear".
- Race day advice: Type "race day".
- Nutrition tips: Type "nutrition".
- Need more help? Type "help".`,
    help: `
I can assist with the following topics:
- **Beginner Advice**: Gear, training, and first steps. Type "beginner".
- **Training Tips**: Weekly plans and practice routines. Type "training".
- **Gear Recommendations**: Specific gear for your level. Type "gear".
- **Race Day Preparation**: Checklists and tips. Type "race day".
- **Nutrition Advice**: Fueling for endurance. Type "nutrition".
- **Open Water Swimming**: Techniques and tips. Type "swimming".
- **FAQs**: Common questions about triathlons. Type "faq".
- Need general guidance? Just ask!
`,
    beginner: `
Getting started with triathlons? Here’s a roadmap:
1. **Start Small**:
   - Begin with a sprint triathlon (short distances).
   - Swim: 750m, Bike: 20km, Run: 5km.
2. **Gear Essentials**:
   - Entry-level road bike, helmet, goggles, running shoes, and a tri-suit.
3. **Training Basics**:
   - Train each sport 2-3 times a week.
   - Add one rest day for recovery.
   - Practice transitions between events (e.g., swim to bike).
`,
    training: `
Training for a triathlon? Here's a guide:
1. **Weekly Schedule**:
   - 2x Swimming: Work on technique and endurance.
   - 2x Cycling: Build speed and distance.
   - 2x Running: Alternate sprints with long runs.
   - 1x Rest Day: Prioritize recovery.
2. **Key Workouts**:
   - Brick sessions (bike + run back-to-back).
   - Long rides to build cycling endurance.
   - Open water swimming practice.
3. **Tracking Progress**:
   - Use apps like Strava or Garmin to monitor performance.
`,
    gear: `
Choosing gear depends on your skill level:
1. **Beginner**:
   - Road bike: Giant Contend or Trek Domane AL.
   - Running shoes: Asics Gel or Brooks Ghost.
   - Swim goggles and entry-level tri-suit.
2. **Intermediate**:
   - Carbon-frame bike with aero bars.
   - Wetsuit for buoyancy: Orca S7 or Zone3.
   - GPS watch for tracking: Garmin Forerunner.
3. **Advanced**:
   - Triathlon-specific bike: Cervelo P-Series.
   - Carbon-plated running shoes for speed.
   - Power meter for cycling precision.
`,
    signup: `
How to sign up for a triathlon:
1. Visit websites like **Ironman.com** or local triathlon organizations.
2. Choose a race that matches your experience (sprint, Olympic, etc.).
3. Register early to secure your spot.
4. Review the race rules and required gear.
5. Train according to the race distances.
6. Join local triathlon clubs for support.
`,
    goodbye: `Thank you for chatting! Feel free to return if you have more questions. Good luck with your triathlon journey!`,
  };

  useEffect(() => {
    if (isFirstGreeting) {
      const greeting = {
        sender: 'bot',
        text: `Hi there! I’m your triathlon assistant. Type "help" to see how I can assist you.`,
      };
      setMessages([greeting]);
      setIsFirstGreeting(false);
    }
  }, [isFirstGreeting]);

  const handleSendMessage = () => {
    if (input.trim() === '') return;

    const userMessage = { sender: 'user', text: input };
    let botResponse;

    const lowerInput = input.toLowerCase();
    if (knowledgeBase[lowerInput]) {
      botResponse = knowledgeBase[lowerInput];
    } else {
      botResponse = `I'm not sure about that. Try asking for "help" to see what I can assist with!`;
    }

    const botMessage = { sender: 'bot', text: botResponse };
    setMessages([...messages, userMessage, botMessage]);
    setInput('');
  };

  const toggleChatbot = () => {
    setIsOpen(!isOpen);
  };

  return (
    <ChatbotContainer>
      <ChatbotHeader onClick={toggleChatbot}>
        {isOpen ? 'Triathlon Assistant' : 'Open Chat'}
      </ChatbotHeader>
      {isOpen && (
        <>
          <ChatWindow>
            {messages.map((msg, index) => (
              <p
                key={index}
                style={{
                  textAlign: msg.sender === 'user' ? 'right' : 'left',
                  margin: '5px 0',
                }}
              >
                <strong>{msg.sender === 'user' ? 'You: ' : 'Bot: '}</strong>
                {msg.text}
              </p>
            ))}
          </ChatWindow>
          <ChatInputContainer>
            <ChatInput
              type="text"
              placeholder="Ask me about triathlons!"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSendMessage()}
            />
            <SendButton onClick={handleSendMessage}>Send</SendButton>
          </ChatInputContainer>
        </>
      )}
    </ChatbotContainer>
  );
};

export default Chatbot;
